
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.728878487201248e+00, -4.628152140237782e+00, -4.486684257176269e+00, -4.290338886076747e+00, -4.022767440564176e+00, -3.668372580878530e+00, -3.219498948935088e+00, -2.689615067583071e+00, -2.129139968076633e+00, -1.616669646338353e+00, -1.131294786701379e+00, -7.432521837545703e-01, -6.440085920686114e-01, -5.301584139949779e-01, -3.911601819154370e-01, -2.599258777974843e-01, -1.511597302700292e-01, -5.634861280314012e-02, 2.626858110659385e-02, 7.099647699396915e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


